import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.BWuWLRhz.js";const b=JSON.parse('{"title":"Interface: RaycastOptions","description":"","frontmatter":{},"headers":[],"relativePath":"api/spool/interfaces/RaycastOptions.md","filePath":"api/spool/interfaces/RaycastOptions.md"}'),r={name:"api/spool/interfaces/RaycastOptions.md"};function n(c,e,i,l,d,p){return a(),o("div",null,[...e[0]||(e[0]=[s('<p><a href="./../">spool</a> / RaycastOptions</p><h1 id="interface-raycastoptions" tabindex="-1">Interface: RaycastOptions <a class="header-anchor" href="#interface-raycastoptions" aria-label="Permalink to &quot;Interface: RaycastOptions&quot;">​</a></h1><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/b41e539939070c2d4bf52934bf50a7ce362c07e6/spool/src/plugins/raycast/index.ts#L23" target="_blank" rel="noreferrer">plugins/raycast/index.ts:23</a></p><p>A reusable <strong>block raycast</strong>: the classic datapack ray that marches the local forward axis (<code>^</code>) through air until it hits a block (or runs out of reach), then runs a caller-supplied body at the hit position. It&#39;s pure command math - no entities, no macros - and inlines into the consuming pack&#39;s own namespace under <code>raycast/&lt;name&gt;</code>.</p><p>The plugin is un-opinionated about <em>what</em> a hit means: you pass an <code>onHit</code> callback (summon a marker, place a block, read the position - whatever), and an optional <code>hitOn</code> filter so only certain blocks count as a hit. <code>grapple</code> is the first consumer (its web anchor), but nothing here is grapple-specific.</p><p>Split by concern: <code>context.ts</code> (the shared <code>raycast.work</code> state + load-init), <code>march.ts</code> (the recursive marcher). This file is the public type + plugin.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="hiton" tabindex="-1">hitOn? <a class="header-anchor" href="#hiton" aria-label="Permalink to &quot;hitOn?&quot;">​</a></h3><blockquote><p><code>readonly</code> <code>optional</code> <strong>hitOn?</strong>: <code>BlockValue</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/b41e539939070c2d4bf52934bf50a7ce362c07e6/spool/src/plugins/raycast/index.ts#L39" target="_blank" rel="noreferrer">plugins/raycast/index.ts:39</a></p><p>Restrict what counts as a hit (a block id, or a tag via <code>Block.tag(&quot;logs&quot;)</code>). The ray still stops at the first non-air block; if that block doesn&#39;t match, <code>onHit</code> simply doesn&#39;t fire (a clean miss). Default: any non-air block is a hit.</p><hr><h3 id="maxsteps" tabindex="-1">maxSteps <a class="header-anchor" href="#maxsteps" aria-label="Permalink to &quot;maxSteps&quot;">​</a></h3><blockquote><p><code>readonly</code> <strong>maxSteps</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/b41e539939070c2d4bf52934bf50a7ce362c07e6/spool/src/plugins/raycast/index.ts#L31" target="_blank" rel="noreferrer">plugins/raycast/index.ts:31</a></p><p>Maximum reach, in <strong>steps</strong> (each step is <code>stepBlocks</code> along <code>^</code>).</p><hr><h3 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to &quot;name&quot;">​</a></h3><blockquote><p><code>readonly</code> <strong>name</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/b41e539939070c2d4bf52934bf50a7ce362c07e6/spool/src/plugins/raycast/index.ts#L29" target="_blank" rel="noreferrer">plugins/raycast/index.ts:29</a></p><p>The marcher&#39;s function path suffix and step-slot name - registers <code>raycast/&lt;name&gt;</code> and counts steps on <code>#&lt;name&gt;_steps</code>. Must be unique per pack; pick a stable, feature-scoped name (e.g. <code>&quot;grapple/web&quot;</code>).</p><hr><h3 id="stepblocks" tabindex="-1">stepBlocks? <a class="header-anchor" href="#stepblocks" aria-label="Permalink to &quot;stepBlocks?&quot;">​</a></h3><blockquote><p><code>readonly</code> <code>optional</code> <strong>stepBlocks?</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/b41e539939070c2d4bf52934bf50a7ce362c07e6/spool/src/plugins/raycast/index.ts#L33" target="_blank" rel="noreferrer">plugins/raycast/index.ts:33</a></p><p>Stride per step along the line of sight, in blocks. Default <code>0.5</code>.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="onhit" tabindex="-1">onHit() <a class="header-anchor" href="#onhit" aria-label="Permalink to &quot;onHit()&quot;">​</a></h3><blockquote><p><strong>onHit</strong>(<code>ctx</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/b41e539939070c2d4bf52934bf50a7ce362c07e6/spool/src/plugins/raycast/index.ts#L44" target="_blank" rel="noreferrer">plugins/raycast/index.ts:44</a></p><p>What to do at the hit. Runs <strong>positioned at the hit block</strong> (and, with <code>hitOn</code>, only when it matches), building commands into the marcher&#39;s on-hit branch.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="ctx" tabindex="-1">ctx <a class="header-anchor" href="#ctx" aria-label="Permalink to &quot;ctx&quot;">​</a></h5><p><code>FunctionContext</code></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p>',36)])])}const u=t(r,[["render",n]]);export{b as __pageData,u as default};
